const fs = require('fs');

function divisors(num) {
    const ret = [];
    let i;
    for (i = 2; i * i < num; i++) {
        if (num % i === 0) {
            ret.push(i);
            ret.push(num / i);
        }
    }
    if (i * i === num) {
        ret.push(i);
    }
    return ret;
}

function main() {
    const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    const out = [];
    let idx = 0;
    while (idx + 2 < data.length) {
        const n = parseInt(data[idx++], 10);
        const m = parseInt(data[idx++], 10);
        const k = parseInt(data[idx++], 10);

        if (n % 2 === 0) {
            out.push('Marsel');
            continue;
        }

        let div = divisors(m);
        if (m > 1) div.push(1);

        let flag = false;
        for (const d of div) {
            if (d >= k) {
                flag = true;
                break;
            }
        }
        out.push(flag ? 'Timur' : 'Marsel');
    }
    console.log(out.join('\n'));
}

main();

